html, body { background: rgb(17, 17, 17); color: rgb(255, 255, 255); font-family: Roboto, sans-serif; font-size: 12px; height: 100%; line-height: 1.4; min-width: 280px; }

body, button, input, textarea { font-family: Roboto, sans-serif; }

h1, h2, h3, h4, h5, h6 { display: inline; font-style: normal; font-weight: normal; margin: 0px; }

a { color: inherit; outline: none 0px; text-decoration: none; }

img { vertical-align: middle; }

ul { list-style: none; margin: 0px; padding: 0px; }

fieldset { border: 0px; margin: 0px; padding: 0px; }

textarea { resize: vertical; }

label.error { color: rgb(211, 0, 0) !important; font-size: 11px; }

div.error { color: rgb(211, 0, 0) !important; font-size: 16px; }

.no-rtl-needed { direction: ltr; }

#overlay { background: rgba(0, 0, 0, 0.5); height: 100%; left: 0px; position: fixed; top: 0px; width: 100%; z-index: 100; }

#wrapper { background: rgb(17, 17, 17); width: 100%; min-width: 280px; }

#header .txt { color: rgb(255, 255, 255); font-size: 13px; height: 15px; line-height: 15px; padding: 0px 4px; }

.btn_deposit { border-radius: 2px; background-color: rgb(0, 153, 0); }

.btn_deposit::before { font-family: iconsDinamicMenu; font-style: normal; font-weight: normal; font-size: 42px; line-height: 28px; width: 30px; display: block; text-align: center; height: 30px; content: ""; }

.orange_line { background: linear-gradient(to right, rgb(0, 0, 0) 0%, rgb(255, 65, 0) 50%, rgb(0, 0, 0) 100%); border: none !important; height: 1px !important; }

.tl_user_popup_container { position: fixed; width: 100%; height: 100%; background: rgba(0, 0, 0, 0.7); z-index: 999; top: 0px; left: 0px; }

.tl_user_popup_header { background-color: rgb(43, 43, 43); border-radius: 2px 2px 0px 0px; height: 47px; width: 100%; align-items: center; padding: 0px 16px; }

.tl_user_head_text { width: calc(100% - 20px); color: rgb(255, 255, 255); font-size: 13px; text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; height: 30px; line-height: 30px; }

.tl_user_chkbox_cont { height: 30px; color: rgb(255, 255, 255); align-items: center; padding: 0px 8px; font-size: 14px; }

.tl_user_chkbox_cont > input { margin-right: 8px; }

.bonuce_balance_currency { padding: 0px 6px; }

.menu_deposit .bonuce_balance_currency { padding: 0px; }

@media screen and (max-width: 350px) {
  #header .txt { font-size: 11px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
}

@media screen and (max-width: 360px) {
  #accountemail { max-width: 148px; }
}

@media only screen and (max-width: 450px) {
  .table-wrapper { width: 280px; overflow-x: scroll; }
}

@media screen and (min-width: 290px) {
  .ui-panel-dismiss-display-push { background: rgba(0, 0, 0, 0.4) !important; }
}

@media screen and (max-width: 490px) {
  #playername { display: none !important; }
  .home-description { max-width: 160px; }
  .inboxtitle { width: 120px; }
  .tgresol { margin-left: 51px !important; }
}

@media screen and (min-width: 491px) {
  .home-description { max-width: 300px; }
  #accountemail { max-width: 250px; }
  .inboxtitle { width: 250px; }
  .tgresol { margin-left: 96px !important; }
}

@media screen and (min-width: 591px) {
  .inboxtitle { width: 350px; }
  #playername a { max-width: 220px !important; }
}

#user-menu { padding-top: 10px; }

#user-menu li { box-sizing: border-box; float: left; width: 50%; }

#user-menu a { display: block; font-size: 12px; line-height: 30px; margin: 0px 10px 0px 5px; text-align: center; }

#user-menu a.btn-sec { margin: 0px 5px 0px 10px; }

.separator { background: rgb(248, 172, 145); height: 1px; margin: 5px auto; width: 90%; }

.sidebar-link { position: relative; z-index: 2; }

.footer_script div { width: 128px; height: 128px; }

.panel { bottom: 0px; overflow: hidden auto; position: absolute; right: 0px; top: 0px; width: 270px; z-index: 9999; max-height: 100dvh; padding-bottom: var(--cwNavbarBottomHeight); }

.panel ul { list-style: none; padding: 0px; }

.panel ul li.activated { border-bottom: 1px solid rgb(242, 77, 16); border-top: 1px solid rgb(242, 77, 16); }

.panel ul li.activatedspan { color: rgb(255, 255, 255); font-weight: bold; text-shadow: rgb(17, 17, 17) 0px 0px 0px; }

.panel ul li.activated a::before { color: rgb(255, 255, 255) !important; }

.panel ul li.label { border: 0px none; line-height: 40px; min-height: 40px; padding-bottom: 0px; padding-left: 0px; }

.panel ul li.active { z-index: 101; }

.panel ul li a.icon-tiles { padding-left: 22px; }

.panel ul li a.icon-rows { padding-left: 22px; }

ul.selector li { padding-left: 22px; }

.letter_icon { line-height: 1 !important; font-size: 35px !important; }

.menu_inbox { column-gap: 5px; }

.collapsible > a { color: rgb(238, 87, 36); display: block; padding: 5px 0px; }

.panel .collapsible > a { color: rgb(255, 255, 255); }

