.gp-app-modal-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(180deg, #8ba014 0%, #687907 100%);
    color: #ffffff !important;
    font-family: 'Roboto', -apple-system, BlinkMacSystemFont, sans-serif;
    font-size: 15px;
    font-weight: 700;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    text-decoration: none;
    padding: 12px 34px;
    border-radius: 25px;
    border: 1px solid #9db715;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.3);
    cursor: pointer;
    transition: transform 0.15s ease, filter 0.15s ease, box-shadow 0.15s ease;
    margin-bottom: 22px;
    user-select: none;
}

.gp-app-modal-btn:hover {
    filter: brightness(1.12);
    transform: translateY(-1px);
    box-shadow: 0 6px 20px rgba(139, 160, 20, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.4);
}

.gp-app-modal-btn:active {
    transform: translateY(1px);
    filter: brightness(0.95);
}

.gp-app-modal-checkbox-row {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    cursor: pointer;
    user-select: none;
    margin: 0;
    font-family: 'Roboto', -apple-system, BlinkMacSystemFont, sans-serif;
}

.gp-app-modal-checkbox-row input[type="checkbox"] {
    display: none;
}

.gp-app-modal-checkbox-box {
    width: 19px;
    height: 19px;
    border: 2px solid #8e9089;
    border-radius: 4px;
    background: rgba(0, 0, 0, 0.25);
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.15s ease;
    flex-shrink: 0;
    box-sizing: border-box;
}

.gp-app-modal-checkbox-row:hover .gp-app-modal-checkbox-box {
    border-color: #b8bcb0;
}

.gp-app-modal-checkbox-row input[type="checkbox"]:checked + .gp-app-modal-checkbox-box {
    background: #7d910f;
    border-color: #8fa612;
}

.gp-app-modal-checkbox-box::after {
    content: "";
    width: 5px;
    height: 9px;
    border: solid #ffffff;
    border-width: 0 2px 2px 0;
    transform: rotate(45deg);
    display: none;
    margin-bottom: 2px;
}

.gp-app-modal-checkbox-row input[type="checkbox"]:checked + .gp-app-modal-checkbox-box::after {
    display: block;
}

.gp-app-modal-checkbox-text {
    color: #e0e2d8;
    font-size: 14px;
    font-weight: 500;
}

.gp-app-modal-phone {
    flex: 0 0 190px;
    width: 190px;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    align-self: stretch;
    overflow: hidden;
    position: relative;
    user-select: none;
    pointer-events: none;
}

.gp-app-modal-phone img {
    height: 100%;
    max-height: 280px;
    object-fit: contain;
    object-position: right center;
    display: block;
}

@media (max-width: 520px) {
    .gp-app-modal-card {
        max-width: 420px;
    }
    .gp-app-modal-content {
        padding: 22px 14px 20px 18px;
    }
    .gp-app-modal-title {
        font-size: 15px;
        margin-bottom: 16px;
    }
    .gp-app-modal-btn {
        padding: 10px 24px;
        font-size: 14px;
        margin-bottom: 18px;
    }
    .gp-app-modal-phone {
        flex: 0 0 120px;
        width: 120px;
    }
}

@media (max-width: 370px) {
    .gp-app-modal-phone {
        display: none;
    }
    .gp-app-modal-content {
        padding: 20px 16px;
    }
}


/* ========================================================
   GRANDPASHABET ODOMETER SLOT REEL TICKER STYLES
   ======================================================== */
.gp-roller-wrap {
    display: inline-flex;
    align-items: center;
    overflow: hidden;
    vertical-align: middle;
    user-select: none;
}

.gp-roller-reel {
    display: inline-block;
    overflow: hidden;
    position: relative;
    text-align: center;
    vertical-align: middle;
    font-variant-numeric: tabular-nums;
}

.gp-roller-strip {
    display: flex;
    flex-direction: column;
    will-change: transform;
    backface-visibility: hidden;
    transition: transform 0.42s cubic-bezier(0.2, 0.85, 0.35, 1.15);
}

.gp-roller-strip span {
    display: block;
    text-align: center;
    font-variant-numeric: tabular-nums;
    font-weight: 800;
}

.gp-roller-sep {
    display: inline-block;
    vertical-align: middle;
    text-align: center;
    font-weight: 800;
}
